var numDistinct = function(s, t) {
    const n = t.length;
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;

    for (const sourceChar of s) {
        for (let j = n; j >= 1; j--) {
            if (sourceChar === t[j - 1]) {
                dp[j] += dp[j - 1];
            }
        }
    }

    return dp[n];
};

